function Meanings({ w, cls }) {
  if (w.meanings && typeof w.meanings === "object") {
    return Object.entries(w.meanings).filter(([, v]) => v).map(([k, v]) => <span key={k} className={cls}>{v}</span>);
  }
  return w.meaning ? <span className={cls}>{w.meaning}</span> : null;
}
