const STANDALONE = typeof window !== "undefined" && !!window.__STANDALONE__;
const KEY_NAME = "lessonstation-api-key";
const MODEL_NAME = "lessonstation-model";
const MODELS = [["claude-sonnet-5-5", "Sonnet 5.5（おすすめ・高品質）"], ["claude-haiku-4-5-20251001", "Haiku 4.5（安い・速い）"]];
const lsGet = (k) => { try { return localStorage.getItem(k) || ""; } catch (e) { return ""; } };

async function askClaude(prompt) {
  const headers = { "Content-Type": "application/json" };
  if (STANDALONE) {
    const key = lsGet(KEY_NAME);
    if (!key) throw new Error("NO_KEY");
    headers["x-api-key"] = key;
    headers["anthropic-version"] = "2023-06-01";
    headers["anthropic-dangerous-direct-browser-access"] = "true";
  }
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers,
    body: JSON.stringify({
      model: STANDALONE ? (lsGet(MODEL_NAME) || MODELS[0][0]) : "claude-sonnet-4-6",
      max_tokens: STANDALONE ? 4000 : 1000,
      messages: [{ role: "user", content: prompt }],
    }),
  });
  const data = await res.json();
  if (data.error) throw new Error(data.error.message || "API_ERROR");
  const text = (data.content || []).map((i) => i.text || "").join("\n");
  const clean = text.replace(/```json|```/g, "").trim();
  return JSON.parse(clean.slice(clean.indexOf("{"), clean.lastIndexOf("}") + 1));
}

