function R({ t }) {
  const s = String(t ?? "");
  const re = /([\u3400-\u9FFF\u3005\u3006\u30F6]+)《([^》]+)》/g;
  const out = [];
  let last = 0, m, k = 0;
  const plain = (x) => x.replace(/《[^》]*》/g, "");
  while ((m = re.exec(s))) {
    if (m.index > last) out.push(plain(s.slice(last, m.index)));
    out.push(<ruby key={k++}>{m[1]}<rt>{m[2]}</rt></ruby>);
    last = re.lastIndex;
  }
  out.push(plain(s.slice(last)));
  return <>{out}</>;
}
const stripFuri = (x) => String(x ?? "").replace(/《[^》]*》/g, "");

function Hl({ text }) {
  const parts = String(text || "").split(/(【[^】]*】)/);
  return parts.map((p, i) => {
    const m = p.match(/^【([^】]*)】$/);
    return m ? <b key={i} className="hl"><R t={m[1]} /></b> : <span key={i}><R t={p} /></span>;
  });
}
