function Sub({ text }) {
  const parts = String(text || "").split(/([（(][^）)]*[）)])/);
  return parts.map((p, i) => {
    const m = p.match(/^[（(]([^）)]*)[）)]$/);
    return m ? <span key={i}>（<u><R t={m[1]} /></u>）</span> : <span key={i}><R t={p} /></span>;
  });
}
