function shrink(file, max = 1000) {
  return new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => {
      const img = new Image();
      img.onload = () => {
        const k = Math.min(1, max / Math.max(img.width, img.height));
        const c = document.createElement("canvas");
        c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);
        c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
        res(c.toDataURL("image/jpeg", 0.82));
      };
      img.onerror = rej; img.src = r.result;
    };
    r.onerror = rej; r.readAsDataURL(file);
  });
}

function loadImg(src) {
  return new Promise((res, rej) => { const im = new Image(); im.onload = () => res(im); im.onerror = rej; im.src = src; });
}
// キャラシートの一番左のイラスト（正面）を見つけて、上半身を切り抜く
async function autoCrop(src) {
  const im = await loadImg(src);
  const W = 600, H = Math.round((im.height / im.width) * W);
  const cv = document.createElement("canvas"); cv.width = W; cv.height = H;
  const g = cv.getContext("2d"); g.drawImage(im, 0, 0, W, H);
  const d = g.getImageData(0, 0, W, H).data;
  const ink = (x, y) => { const i = (y * W + x) * 4; return d[i + 3] > 40 && (d[i] < 225 || d[i + 1] < 225 || d[i + 2] < 225); };
  const full = { x: 0, y: 0, w: 1, h: 1, iw: im.width, ih: im.height };
  const top = Math.round(H * 0.3);
  const col = Array.from({ length: W }, (_, x) => { let n = 0; for (let y = 0; y < top; y++) if (ink(x, y)) n++; return n; });
  const x0 = col.findIndex((n) => n > 2);
  if (x0 < 0) return full;
  let x1 = x0, gap = 0;
  for (let x = x0; x < W; x++) { if (col[x] > 2) { x1 = x; gap = 0; } else if (++gap > 8) break; }
  const xa = Math.max(0, x0 - Math.round(0.03 * W)), xb = Math.min(W - 1, x1 + Math.round(0.03 * W));
  const row = Array.from({ length: H }, (_, y) => { let n = 0; for (let x = xa; x <= xb; x++) if (ink(x, y)) n++; return n; });
  const y0 = row.findIndex((n) => n > 1);
  if (y0 < 0) return full;
  const lim = Math.max(3, Math.round(0.03 * (xb - xa + 1)));
  let y1 = H - 1, run = 0;
  for (let y = y0 + Math.round(0.3 * H); y < H; y++) {
    if (row[y] <= lim) { if (++run >= 2) { y1 = y - 2; break; } } else run = 0;
  }
  while (y1 > y0 && row[y1] === 0) y1--;
  let xa2 = xb, xb2 = xa;
  for (let x = xa; x <= xb; x++) { let n = 0; for (let y = y0; y <= y1; y++) if (ink(x, y)) n++; if (n > 1) { xa2 = Math.min(xa2, x); xb2 = Math.max(xb2, x); } }
  if (xb2 <= xa2) { xa2 = xa; xb2 = xb; }
  y1 = Math.min(y1, y0 + Math.round(1.35 * (xb2 - xa2)));
  const pad = 6;
  const cx0 = Math.max(0, xa2 - pad), cy0 = Math.max(0, y0 - pad), cx1 = Math.min(W, xb2 + pad), cy1 = Math.min(H, y1 + pad);
  return { x: cx0 / W, y: cy0 / H, w: (cx1 - cx0) / W, h: (cy1 - cy0) / H, iw: im.width, ih: im.height };
}
async function cropToIcon(src, c) {
  const im = await loadImg(src);
  const sx = c.x * im.width, sy = c.y * im.height, sw = c.w * im.width, sh = c.h * im.height;
  const k = Math.min(1, 420 / sh);
  const cv = document.createElement("canvas"); cv.width = Math.round(sw * k); cv.height = Math.round(sh * k);
  cv.getContext("2d").drawImage(im, sx, sy, sw, sh, 0, 0, cv.width, cv.height);
  return cv.toDataURL("image/png");
}

async function copyText(t) {
  try { await navigator.clipboard.writeText(t); return true; } catch (e) {
    const ta = document.createElement("textarea"); ta.value = t; document.body.appendChild(ta);
    ta.select(); let ok = false; try { ok = document.execCommand("copy"); } catch (e2) {}
    document.body.removeChild(ta); return ok;
  }
}

const LANG_HINTS = [
  ["韓国語", /韓国|한국|コリア|korea/i],
  ["英語", /英語|アメリカ|イギリス|オーストラリア|フィリピン|インド|english|英語圏/i],
  ["中国語", /中国|台湾|香港|chin|中文/i],
];
function guessLangs(level, text) {
  const found = LANG_HINTS.filter(([, re]) => re.test(text || "")).map(([l]) => l);
  if (found.length) return found;
  if (["小学生", "中学生", "高校生"].includes(normLevel(level))) return ["韓国語"];
  return null;
}

const groupOf = (f) => (f.profileName && f.profileName.trim()) || f.level;
const lessonId = (f) => `${groupOf(f)}-${f.no}`;

const dialogueText = (d) => `場面: ${d.scene}\n` + d.lines.map((l) => `${l.speaker}：${l.text}`).join("\n");

